## Circular Doubly Linked List
![[Pasted image 20251127105002.png]]
- combination of both circular and Doubly type of linked list
```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
    struct Node* prev;
};

struct Node* head = NULL;

struct Node* createNode(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = newNode->prev = NULL;
    return newNode;
}

// Insert at the end of the circular doubly linked list
void insertEnd(int value) {
    struct Node* newNode = createNode(value);

    if (head == NULL) {
        head = newNode;
        head->next = head;
        head->prev = head;
        return;
    }

    struct Node* last = head->prev;

    last->next = newNode;
    newNode->prev = last;
    newNode->next = head;
    head->prev = newNode;
}

// Display forward
void displayForward() {
    if (head == NULL) {
        printf("List is empty\n");
        return;
    }

    struct Node* temp = head;
    printf("Forward: ");

    do {
        printf("%d ", temp->data);
        temp = temp->next;
    } while (temp != head);

    printf("\n");
}

// Display backward
void displayBackward() {
    if (head == NULL) {
        printf("List is empty\n");
        return;
    }

    struct Node* temp = head->prev;
    printf("Backward: ");

    do {
        printf("%d ", temp->data);
        temp = temp->prev;
    } while (temp != head->prev);

    printf("\n");
}

// Delete a specific value
void deleteNode(int value) {
    if (head == NULL) return;

    struct Node* temp = head;

    while (temp->data != value) {
        temp = temp->next;
        if (temp == head) {
            printf("Value not found.\n");
            return;
        }
    }

    // Case: Only one node left
    if (temp->next == head && temp->prev == head) {
        head = NULL;
        free(temp);
        return;
    }

    temp->prev->next = temp->next;
    temp->next->prev = temp->prev;

    // Deleting the head node
    if (temp == head)
        head = temp->next;

    free(temp);
}

int main() {
    insertEnd(10);
    insertEnd(20);
    insertEnd(30);
    insertEnd(40);

    displayForward();   // 10 20 30 40
    displayBackward();  // 40 30 20 10

    deleteNode(20);

    displayForward();   // 10 30 40
    displayBackward();  // 40 30 10

    return 0;
}
```

## Header Circular Doubly Linked List
![[Pasted image 20251127110128.png]]
```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *prev;
    struct Node *next;
} Node;

// Create header node (empty list)
Node* createHeader() {
    Node *header = (Node*)malloc(sizeof(Node));
    if (!header) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    header->next = header;  // circular to itself
    header->prev = header;
    return header;
}

// Create a normal data node
Node* createNode(int data) {
    Node *newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->next = newNode->prev = NULL;
    return newNode;
}

// Insert at end (before header)
void insertEnd(Node *header, int data) {
    Node *last = header->prev;   // last node (or header if empty)
    Node *newNode = createNode(data);

    newNode->next = header;
    newNode->prev = last;

    last->next = newNode;
    header->prev = newNode;
}

// Insert at beginning (after header)
void insertBeginning(Node *header, int data) {
    Node *first = header->next;  // first node (or header if empty)
    Node *newNode = createNode(data);

    newNode->next = first;
    newNode->prev = header;

    header->next = newNode;
    first->prev = newNode;
}

// Delete first occurrence of key
void deleteNode(Node *header, int key) {
    Node *temp = header->next;

    while (temp != header && temp->data != key) {
        temp = temp->next;
    }

    if (temp == header) {
        printf("Key %d not found\n", key);
        return;
    }

    temp->prev->next = temp->next;
    temp->next->prev = temp->prev;

    free(temp);
}

// Display list forward
void displayForward(Node *header) {
    Node *temp = header->next;
    if (temp == header) {
        printf("List is empty\n");
        return;
    }

    printf("Forward: ");
    while (temp != header) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

// Display list backward
void displayBackward(Node *header) {
    Node *temp = header->prev;
    if (temp == header) {
        printf("List is empty\n");
        return;
    }

    printf("Backward: ");
    while (temp != header) {
        printf("%d ", temp->data);
        temp = temp->prev;
    }
    printf("\n");
}

// Free entire list (including header)
void freeList(Node *header) {
    Node *curr = header->next;
    while (curr != header) {
        Node *next = curr->next;
        free(curr);
        curr = next;
    }
    free(header);
}

int main() {
    Node *header = createHeader();

    insertEnd(header, 10);
    insertEnd(header, 20);
    insertBeginning(header, 5);
    insertEnd(header, 30);

    displayForward(header);
    displayBackward(header);

    deleteNode(header, 20);
    displayForward(header);

    freeList(header);
    return 0;
}
```

